// ==================== CUTSCENES ====================
// Простой движок кат-сцен: последовательность «кадров» с движением камеры и субтитрами.
const CINE = { shots: null, i: 0, t: 0, onEnd: null, txt: '', shown: 0 };
const _cA = new THREE.Vector3(), _cB = new THREE.Vector3();
const V = (x, y, z) => new THREE.Vector3(x, y, z);
