// ==================== FLOW ====================
function startLevel() {
  audioInit(); fade(true);
  setTimeout(() => {
    menuMode = false; if (menuModel) { scene.remove(menuModel); menuModel = null; }
    clearDrones(); buildLevel(G.levelIdx); setupPlayerModel(); loadout(); G.stats = { time: 0, helped: 0, res: 0, downed: 0, retries: 0 };
    G.cine = true; startSegment(0, false); snapshot(); G.levelTime = 0; show(null); G.cine = false; $('#obj')._h = '';
    const begin = () => {
      G.state = 'play'; $('#hud').classList.remove('hidden'); $('#touch').classList.toggle('hidden', !G.touch); camera.fov = 64; camera.updateProjectionMatrix(); CAM.yaw = 0; CAM.pitch = .1;
      if (G.levelIdx === 0) { tip('Вы вышли из магазина. Идите по улице (W A S D' + (G.touch ? ' / джойстик слева' : '') + ').'); }
      else say(CH().lines.exit, 3);
      if (!G.touch) lockPointer();
    };
    fade(false);
    if (G.levelIdx === 0) { G.seenPrologue = true; save(); playCine(prologueShots(), begin); }
    else playCine(levelIntroShots(), begin);
  }, 350);
}
